    ('r_hearth_amulet', 'none', 'jewel', "Amulet of Travia's Hearth: a silver chain. A tiny tin goose, warm like a kitchen fire.", ['r_hearth_amulet']),
    ('r_phex_ring', 'none', 'jewel', "Ring of Phex's Fingers: a silver ring. The fox on the seal winks if you look at it sideways.", ['r_phex_ring']),
    ('r_aves_ring', 'none', 'jewel', "Wanderer's Ring of Aves: a silver ring. Left at the shrine by a traveller who no longer needed luck.", ['r_aves_ring']),
    ('a_unbowed', 'blue', 'jewel', 'Amulet of the Unbowed: a silver chain. A broken chain on a silver thread. You will not kneel.', ['a_unbowed']),
    ('a_ox_ring', 'blue', 'jewel', 'Ring of the Ox: a gold ring. A heavy band of black iron set with a golden ox-head.', ['a_ox_ring']),
    ('a_fletcher_ring', 'blue', 'jewel', "Fletcher's Thumb Ring: a silver ring. A horn thumb ring that never slips.", ['a_fletcher_ring']),
    ('a_summoner_torc', 'blue', 'jewel', "Summoner's Torc: a gold chain. A druidic torc of twisted gold; animals come when it hums.", ['a_summoner_torc']),
    ('a_clear_mind', 'blue', 'jewel', 'Ring of the Clear Mind: a silver ring. A Hesinde-blue sapphire that settles the thoughts.', ['a_clear_mind']),
    ('a_salamander_phial', 'blue', 'jewel', 'Salamander Phial: a gold chain. A sealed vial on a chain, holding a single living ember.', ['a_salamander_phial']),
    ('a_umbracor_splinter', 'blue', 'jewel', "Splinter of Umbracor's Heart: a gold chain. A sliver of the good dragon's heart, torn loose when the Purplewyrm fell. Where is the rest?.", ['a_umbracor_splinter']),
    ('r_artisan_band', 'none', 'jewel', "Artisan's Band: a silver ring. A guild ring engraved with three tiny tools: hammer, knife, scale.", ['r_artisan_band']),
    ('a_masterwork_band', 'blue', 'jewel', "Master Artisan's Band: a gold ring. The same three tools, in gold. Murolosh smiths nod when they see it.", ['a_masterwork_band']),
    ('a_amazon_torc', 'blue', 'jewel', 'Torc of the Free Amazons: a gold chain. Taken from the Mactaleanata leader. Rhulana knows what it means.', ['a_amazon_torc']),
    ('a_valonion_string', 'blue', 'jewel', "Valonion's Bowstring Ring: a silver ring. A ring wound from the string of an elven bow.", ['a_valonion_string']),
    ('am_barbed_arrow', 'none', 'weapon', 'Barbed Arrows: a small bundle of three arrows. Wicked barbs that tear on the way out. Diagonal.', ['am_barbed_arrow']),
    ('am_barbed_bolt', 'none', 'weapon', 'Barbed Bolts: a small bundle of three crossbow bolts. Crossbow bolts with barbed heads. Diagonal.', ['am_barbed_bolt']),
    ('am_kosh_arrow', 'none', 'weapon', 'Kosh-steel Arrows: a small bundle of three arrows. Heads of Kosh steel punch through leather and mail. Diagonal.', ['am_kosh_arrow']),
    ('am_thunder_arrow', 'none', 'weapon', 'Thunderhead Arrows: a small bundle of three arrows. A chip of gemstone in each head stores a spark. Diagonal.', ['am_thunder_arrow']),
    ('am_frost_arrow', 'none', 'weapon', "Frost-fletched Arrows: a small bundle of three arrows. Harpy feathers dipped in meltwater from Firun's glaciers. Diagonal.", ['am_frost_arrow']),
    ('am_dwarf_bolt', 'none', 'weapon', 'Dwarven Steel Bolts: a small bundle of three crossbow bolts. Square-headed bolts of Angrosch steel. Diagonal.', ['am_dwarf_bolt']),
    ('am_wyrmfang_arrow', 'none', 'weapon', "Wyrmfang Arrows: a small bundle of three arrows. Tipped with splinters of a dragon's tooth. They burn going in. Diagonal.", ['am_wyrmfang_arrow']),
    ('tr_whitefur_fang', 'blue', 'jewel', 'Fang of White Fur: one huge pale white wolf fang, longer than a finger, with a few white hairs at the root.', ['tr_whitefur_fang']),
    ('trap_frost', 'blue', 'jewel', 'Frost Snare: a hunting snare of pale blue crab-shell and sinew, rimed with frost.', ['trap_frost']),
    ('trap_web', 'blue', 'jewel', 'Spider-silk Web: a folded bundle of thick sticky white spider silk with a small iron ring.', ['trap_web']),
    ('trap_venom', 'blue', 'jewel', 'Venom Spikes: a small wooden board of iron spikes smeared with amber venom.', ['trap_venom']),
    ('trap_thunder', 'blue', 'jewel', 'Thunder Mine: a cut gemstone bound in iron bands with a crackling violet spark inside.', ['trap_thunder']),
    ('trap_hex', 'violet', 'jewel', 'Hex Glyph: a round slate disc carved with a glowing violet curse rune.', ['trap_hex']),
    ('trap_wyrmfire', 'violet', 'jewel', 'Wyrmfire Trap: an iron jaw trap with a glowing red dragon-scale plate on its trigger.', ['trap_wyrmfire']),
    # ---- v2.4 heirloom sets, reforges, Gwendala pass (web sheets; armory items -> copy to armory_icons_v2) ----
    ('h_rh1', 'blue', 'jewel', "Lion's Tooth of Kurkum: a single lion tooth pendant on a thin gold chain.", ['h_rh1']),
    ('h_rh2', 'violet', 'jewel', 'Mane of the Lioness: a lion tooth wrapped in a mane of braided gold wire, on a gold chain.', ['h_rh2']),
    ('h_rh3', 'gold', 'jewel', 'Pride of Kurkum: a lion tooth set in a radiant golden lion mane with a small red gem, on a heavy gold chain.', ['h_rh3']),
    ('h_rh4', 'red', 'jewel', 'Heart of the Lion Queen: a magnificent golden lion head amulet with a purple dragon scale as its mane and ruby eyes.', ['h_rh4']),
    ('h_fo1', 'blue', 'jewel', "Ferolax's Hammer-Ring: a plain heavy gold ring engraved with a tiny hammer.", ['h_fo1']),
    ('h_fo2', 'violet', 'jewel', 'Anvil-Ring of Ferolax: a thick gold ring shaped like a small anvil band with hammer marks.', ['h_fo2']),
    ('h_fo3', 'gold', 'jewel', 'Forgefire Ring: a dwarven ring of folded steel and gold with a glowing orange forge-gem.', ['h_fo3']),
    ('h_fo4', 'red', 'jewel', "Ferolax's Unbroken Oath: a massive dwarven ring with a purple dragon-scale inlay and runes glowing like embers.", ['h_fo4']),
    ('h_gw1', 'blue', 'jewel', 'Seed of the Moon-Tree: a small pale seed in a silver cage pendant on a fine chain.', ['h_gw1']),
    ('h_gw2', 'violet', 'jewel', 'Song of Sala: a silver cage pendant with a tiny green sprout growing out of the seed.', ['h_gw2']),
    ('h_gw3', 'gold', 'jewel', "Moonwarden's Oath: a silver pendant holding a small glowing moon-white sapling with silver leaves.", ['h_gw3']),
    ('h_gw4', 'red', 'jewel', "Sala Mandra's Last Song: a silver pendant of a blossoming moon-tree wrapped around a purple dragon scale, white flowers glowing.", ['h_gw4']),
    ('h_th1', 'blue', 'jewel', 'Grimoire Locket: a silver locket open to show one folded page of a grimoire.', ['h_th1']),
    ('h_th2', 'violet', 'jewel', 'The Stolen Grimoire: a tiny leather-bound book hanging on a silver chain, glowing blue runes on the cover.', ['h_th2']),
    ('h_th3', 'gold', 'jewel', 'Grimoire of the Margins: a small thick grimoire on a chain, pages bristling with notes, faint violet glow from inside.', ['h_th3']),
    ('h_th4', 'red', 'jewel', 'The Unwritten Page: a small grimoire bound in a purple dragon scale on a silver chain, open on one blank shining page.', ['h_th4']),
    ('lq_helm', 'violet', 'armour', "Lion Queen's Crest-Helm: a kurkumian helmet. A Kurkum helm with a golden lion crest. Part of the Regalia of the Lion Queen.", ['lq_helm']),
    ('lq_cuirass', 'gold', 'armour', "Lion Queen's Cuirass: a kurkumian amazon armor. Gilded plate over red leather. Sabeth stole it when Kurkum cast her out. Part of the Regalia of the Lion Queen.", ['lq_cuirass']),
    ('lq_grips', 'violet', 'armour', "Lion Queen's Grips: a heavy leather gloves. Red leather sword-grips with gilded knuckles. Part of the Regalia of the Lion Queen.", ['lq_grips']),
    ('lq_sabatons', 'gold', 'armour', "Lion Queen's Sabatons: a kurkumian plated boots. Kurkum plated boots worked with lion claws. Part of the Regalia of the Lion Queen.", ['lq_sabatons']),
    ('fx_helm', 'violet', 'armour', "Ferolax's Crown-Helm: a dragonslayer's helm. The dragonslayer helm of Ferolax. Grimbart took it into exile. Part of Ferolax's Forge-Panoply.", ['fx_helm']),
    ('fx_plate', 'gold', 'armour', "Ferolax's Forge-Plate: a dwarven plate armor. Dwarven plate with an anvil worked into the chest. Part of Ferolax's Forge-Panoply.", ['fx_plate']),
    ('fx_gauntlets', 'violet', 'armour', "Ferolax's Gauntlets: a dwarven gauntlets. Heavy dwarven gauntlets, still black from his forge. Part of Ferolax's Forge-Panoply.", ['fx_gauntlets']),
    ('fx_boots', 'gold', 'armour', "Ferolax's Plated Boots: a dwarven plated boots. Dwarven plated boots that have never taken a step back. Part of Ferolax's Forge-Panoply.", ['fx_boots']),
    ('mw_hood', 'violet', 'armour', "Moonwarden's Hood: a hunter's cap. A grey-green hunter's hood. Faelwen took it from a warden he sold. Part of the Moonwarden's Raiment.", ['mw_hood']),
    ('mw_jerkin', 'gold', 'armour', "Moonwarden's Jerkin: a elven leather armor. Elven leather that drinks moonlight. The ghost of its owner guarded it. Part of the Moonwarden's Raiment.", ['mw_jerkin']),
    ('mw_bracers', 'violet', 'armour', "Moonwarden's Bracers: a iryan leather gloves. Iryan leather bracers stitched with silver leaves. Part of the Moonwarden's Raiment.", ['mw_bracers']),
    ('mw_treads', 'gold', 'armour', "Moonwarden's Treads: a iryan leather shoes. Soft Iryan boots that leave no track. Part of the Moonwarden's Raiment.", ['mw_treads']),
    ('gt_cowl', 'violet', 'armour', "Spellthief's Cowl: a wanderer's hat. A wide hat with a hidden pocket for stolen spells. The necromancer of Tallon was wearing it. Part of the Stolen Grimoire.", ['gt_cowl']),
    ('gt_coat', 'gold', 'armour', "Spellthief's Coat: a leather cuirass. A dark leather coat lined with pages. Arrows hate it; so do spells. Part of the Stolen Grimoire.", ['gt_coat']),
    ('gt_gloves', 'violet', 'armour', "Ink-Stained Gloves: a gloves of shadow. Ravena's gloves, stained with ink and older things. Part of the Stolen Grimoire.", ['gt_gloves']),
    ('gt_boots', 'gold', 'armour', 'Margin-Walker Boots: a high top boots. High boots that walk where the map has no ink. Part of the Stolen Grimoire.', ['gt_boots']),
    ('m_rf_lion_queen', 'red', 'weapon', "Fang of the Lion Queen: a amazon saber. Rondra's saber, reforged with a scale of Japhgur. Rhulana:. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_lion_queen']),
    ('m_rf_rondra_verdict', 'red', 'weapon', "Rondra's Verdict: a amazon saber. Sabeth's saber, purified and reforged. The outcast's blade now judges for Kurkum. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_rondra_verdict']),
    ('m_rf_last_oath', 'red', 'weapon', 'Last Oath, Fulfilled: a dragonslayer hammer. The dragonslayer hammer, finished at last with the scale of the dragon it was sworn against. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.', ['m_rf_last_oath']),
    ('m_rf_exile', 'red', 'weapon', "Cleaver of the Returned Exile: a stonesplitter. Grimbart's axe, reforged in Murolosh. Forgrimm brought it home; the exile's name is spoken again. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_exile']),
    ('m_rf_sala', 'red', 'weapon', "Sala Mandra's Lullaby: a elven bow. The elven queen's bow, restrung with dragon sinew. Its arrows sing their targets to sleep. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_sala']),
    ('m_rf_duskarrow', 'red', 'weapon', "Duskarrow Redeemed: a elven bow. Faelwen's bow, reborn in Gwendala's hands. It hunts only those who hunt elves now. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_duskarrow']),
    ('m_rf_crimson', 'red', 'weapon', "Crimson Vow, Unbroken: a dirk. Ravena's dirk, reforged around a scale. The Circle's oath is yours alone now. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_crimson']),
    ('m_rf_phex', 'red', 'weapon', "Phex's Final Jest: a dragon's tooth. The dragon-tooth dagger, stolen from Japhgur twice, finally fitted with a piece of Japhgur. Phex is delighted. Ornate final mythic version with a purple dragon-scale inlay. Diagonal.", ['m_rf_phex']),
    ('a_moonbow', 'blue', 'weapon', 'Moonbow: a elven bow. A pale elven bow. Its arrows find what the night hides.', ['a_moonbow']),
    ('a_moonglove', 'blue', 'armour', "Archer's Moon-Glove: a silvan elf gloves. A soft elven shooting glove with a silver finger-guard.", ['a_moonglove']),
    ('a_hawkstring', 'blue', 'weapon', 'Hawkstring: a short bow. A short bow strung with hawk-gut. Quick as a stoop.', ['a_hawkstring']),
    ('s_thornwood', 'violet', 'weapon', 'Thornwood Warbow: a war bow. A heavy war bow of black thornwood. Its arrows leave the wound open.', ['s_thornwood']),
    ('s_silverleaf', 'violet', 'weapon', 'Silverleaf Longbow: a tiik tok longbow. A longbow of silverleaf. Frost gathers on the string.', ['s_silverleaf']),
    ('am_moonsilver_arrow', 'none', 'weapon', 'Moonsilver Arrows: a small bundle of three arrows. Silver-tipped: the dead fear them. Diagonal.', ['am_moonsilver_arrow']),
    ('am_hawk_arrow', 'none', 'weapon', 'Hawk-feather Arrows: a small bundle of three arrows. Fletched with hawk feathers: they bite deeper. Diagonal.', ['am_hawk_arrow']),
    ('am_sleepthorn_arrow', 'none', 'weapon', 'Sleepthorn Arrows: a small bundle of three arrows. Tipped with sleepthorn sap: the target staggers. Diagonal.', ['am_sleepthorn_arrow']),
