    P = os.path.join(A, 'prompts')
    if sys.argv[1] == 'prompts':
        with open(os.path.join(P, 'batch_rm_list.txt'), 'w', newline='\n') as lst:
            for key, glow, ref, desc, _ in JOBS:
                open(os.path.join(P, f'rm_{key}.txt'), 'w', encoding='utf-8', newline='\n').write(
                    f'Exactly one single object, not a sheet, not a grid, not several icons: one inventory icon for the RPG Drakensang in the same painted style '
                    f'as the attached icon: {desc}. Same lighting, colour saturation and painted texture as the attached icon. {GLOW[glow]} Transparent background, no text.\n')
                open(os.path.join(P, f'rm_{key}.ref'), 'w', newline='\n').write(f'assets/armory_icons_v2/ref/{ref}.png')
                lst.write(f'rm_{key}\n')
        print(len(JOBS), 'prompts')
    else:
        sys.path.insert(0, os.path.join(HERE, '..'))
        from PIL import Image
        from dsa import VANILLA_ICON_HEADER, encode_dxt3
        os.makedirs(OUTD, exist_ok=True); n = 0
        for key, glow, _, _, items in JOBS:
            src = os.path.join(A, 'src', f'rm_{key}.png')
            if not os.path.exists(src): print('missing', key); continue
            im = Image.open(src).convert('RGBA')
            bb = im.split()[3].point(lambda v: 255 if v > 20 else 0).getbbox(); im = im.crop(bb); w, h = im.size; s = int(max(w, h) * 1.06)
            sq = Image.new('RGBA', (s, s), (0, 0, 0, 0)); sq.paste(im, ((s - w) // 2, (s - h) // 2)); out = sq.resize((128, 128), Image.LANCZOS)
            out.save(os.path.join(OUTD, f'rm_{key}_128.png'))
            reglow = os.path.exists(src[:-4] + '.reglow')   # split from a web sheet: add native shadow + tier glow here
            for it in items:
                dst = os.path.join(OUTD, f'arm_{it}.dds')
                if reglow:
                    from dsa import make_icon
                    make_icon(out, dst, {'none': 'regular', 'blue': 'amazing', 'violet': 'superrare', 'gold': 'legendary', 'red': 'mythic'}[glow])
                else: open(dst, 'wb').write(VANILLA_ICON_HEADER + encode_dxt3(out))
                n += 1
        print('icons written', n)
